const body = $('Demande').first().json.body || {};
const row = ($('Lire la vidéo').first().json.data || [])[0];
if (!row) throw new Error('Vidéo inconnue : ' + body.video_id);
const src = ($input.first().json.data || []).find(s => s.channel_id === row.channel_id);
if (src && src.statut !== 'usable') throw new Error(`${row.source_nom} est en « ${src.statut} » : pas d'extrait de cette source (règle anti-strike). Le sujet peut être repris depuis une autre source.`);
return [{ json: { ...row, exclure: body.exclure || null } }];

const v = $('Infos vidéo').first().json;
const t = $('Transcrire').first().json;
// Phase d'exploration (200 premiers Shorts) : on n'applique PAS les leçons, on collecte des données variées.
const phrases = (t.phrases || []).map(p => `[${p.start}-${p.end}] ${p.texte}`).join('\n');
const excl = v.exclure ? `\nNe reprends PAS le passage ${v.exclure[0]}-${v.exclure[1]} s (déjà proposé et refusé) : choisis un autre moment.` : '';
const system = `Tu es monteur vidéo pour « L’Extrait politique », chaîne de Shorts qui fait le zapping des meilleurs moments de l'actualité française (politiques, mais aussi analyses de spécialistes, intellectuels, experts).
Tu reçois la transcription horodatée (en secondes) d'une vidéo. Choisis LE meilleur extrait pour un Short :
- durée : entre 9 et 150 secondes, choisie selon le moment lui-même. Un clash ou une punchline peut durer 10-20 s ; une démonstration, un raisonnement de spécialiste ou un échange argumenté peut aller jusqu'à 2 min 30. Ne rallonge jamais artificiellement, et ne coupe pas un raisonnement en plein milieu ;
- compréhensible seul, sans contexte (le spectateur doit saisir l'enjeu en 3 secondes) ;
- commence au DÉBUT d'une phrase et finit à la FIN d'une phrase (utilise exactement les horodatages fournis) ;
- privilégie : clash, punchline, contradiction, aveu, chiffre choc, émotion, analyse éclairante ;
- reste neutre : tu montres le moment, tu ne prends pas parti.
Propose aussi un titre à incruster (6 mots max, percutant, fidèle aux propos, sans majuscules partout) et une description YouTube courte (2 phrases + 3 hashtags).
Enfin, ANALYSE l'extrait que tu as choisi (l'extrait seul, pas toute la vidéo) avec exactement ces valeurs :
- intervenant : nom complet de la ou des personnes qui parlent dans l'extrait (max 2, séparées par une virgule) ;
- type_intervenant : politique | expert | journaliste | citoyen | autre ;
- notoriete : tres_connu | connu | peu_connu (notoriété de l'intervenant auprès du grand public français) ;
- camp : LFI | PS | Écologistes | PCF | extrême gauche | Renaissance/centre | LR | RN | Reconquête | souverainistes | gouvernement | institutions | plusieurs camps | non partisan (experts, journalistes, citoyens sans étiquette) ;
- sujet : l'événement précis, 8 mots max ;
- theme : sécurité | immigration | économie | budget/dette | social | travail/retraites | éducation | santé | justice | institutions | international | guerre/défense | écologie/énergie | médias | société | religion/laïcité | féminisme | élections | autre ;
- lien_actu : chaud (sujet du jour, en cours) | recent (sujet de la semaine) | froid (sujet de fond, intemporel) ;
- signification : faible | moyen | fort (importance de ce qui est dit pour la société française) ;
- type_moment : clash | moment_fort | moment_emouvant ;
- ton : colere | indignation | humour | ironie | gravite | emotion | calme ;
- accroche : phrase_choc | question | attaque | chiffre | demarrage_lent (ce qui se passe dans les 2-3 premières secondes de l'extrait) ;
- type_titre : citation | question | information | consequence | interpellation (nature du titre que tu proposes).
Réponds UNIQUEMENT en JSON : {"start": 0, "end": 0, "titre": "...", "description": "...", "raison": "...", "analyse": {"intervenant": "...", "type_intervenant": "...", "notoriete": "...", "camp": "...", "sujet": "...", "theme": "...", "lien_actu": "...", "signification": "...", "type_moment": "...", "ton": "...", "accroche": "...", "type_titre": "..."}}`;
const user = `Vidéo : ${v.titre}\nSource : ${v.source_nom}\nPubliée le : ${v.publiee_le || '?'}\nAngle éditorial suggéré : ${v.angle || '-'}${excl}\n\nTranscription :\n${phrases}`;
return [{ json: { duree: t.duree_s, body: { model: 'claude-sonnet-4-5', max_tokens: 1500, system, messages: [{ role: 'user', content: user }] } } }];

const v = $('Infos vidéo').first().json;
const duree = $('Préparer la demande').first().json.duree;
const txt = ($input.first().json.content || []).map(c => c.text || '').join('');
let c;
try { c = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1)); } catch (e) { throw new Error('Choix Claude illisible : ' + txt.slice(0, 200)); }
let start = Math.max(0, +c.start), end = Math.min(+c.end, duree || +c.end);
if (!(end > start)) throw new Error('Intervalle invalide');
if (end - start > 155) end = start + 150;   // plage voulue : 9 s à 2 min 30
const a = c.analyse || {};
const analyse = { ...a, format: 'extrait_seul', chaine: v.source_nom, duree_s: Math.round(end - start) };
return [{ json: { video_id: v.video_id, source_nom: v.source_nom, titre_video: v.titre, start, end, titre: c.titre, description: c.description, raison: c.raison, analyse } }];

const c = $('Choix du moment').first().json;
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const mmss = s => `${Math.floor(s/60)}:${String(Math.round(s%60)).padStart(2,'0')}`;
const _cap = `🤖 <b>Short prêt — publication automatique au prochain créneau</b>\n✂️ <b>${esc(c.titre)}</b>\n📺 ${esc(c.source_nom)} · ${mmss(c.start)} → ${mmss(c.end)} (${Math.round(c.end - c.start)} s)\n🧠 ${esc(c.raison)}\n\n📝 ${esc(c.description)}`;
return [{ json: { caption: _cap.length > 1020 ? _cap.slice(0, 1015) + '…' : _cap,
  cb_ok: `clip_ok|${c.video_id}`, cb_retry: `clip_retry|${c.video_id}|${Math.round(c.start)}|${Math.round(c.end)}`, cb_no: `clip_no|${c.video_id}` }, binary: $input.first().binary }];
